{"file_path":"src/filter.js","content":"/**
 * The `filter` subcommand: keep the rows whose named column matches an
 * operator and a value.
 *
 * This module belongs to the `filter` department, whose branch carries no
 * other department's file, so it imports nothing at all — not even the shared
 * reader. `bin/csv-tools.js` is the only place a subcommand and the reader
 * meet.
 */

/** The five operators, per SPEC.md; anything else is a usage failure. */
const OPERATORS = new Set(['=', '!=', '<', '>', 'contains']);

/**
 * A number as SPEC.md defines one, for the whole program: no leading `+`, no
 * leading zero, no bare `.5`, no `NaN` and no `Infinity`, so a column of
 * zero-padded identifiers stays text.
 */
const NUMBER = /^-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?$/;

/**
 * @param {string} message diagnostic, without prefix or terminator
 * @returns {Error} a wrong-command-line failure
 */
function usageError(message) {
  const error = new Error(message);
  error.code = 'usage';
  return error;
}

/**
 * @param {string} message diagnostic, without prefix or terminator
 * @returns {Error} a wrong-input failure
 */
function dataError(message) {
  const error = new Error(message);
  error.code = 'data';
  return error;
}

/**
 * @param {string} value candidate text
 * @returns {boolean} whether it is a number
 */
function isNumber(value) {
  return NUMBER.test(value);
}

/**
 * Order two cells: numerically when both are numbers, otherwise as strings by
 * UTF-16 code unit — which is exactly what `<` and `>` do on JavaScript
 * strings.
 *
 * @param {string} cell the row's value in the named column
 * @param {string} value the operand from the command line
 * @returns {number} negative, zero or positive as cell orders before, with or
 *   after value
 */
function compare(cell, value) {
  if (isNumber(cell) && isNumber(value)) {
    return Number(cell) - Number(value);
  }
  if (cell < value) return -1;
  if (cell > value) return 1;
  return 0;
}

/**
 * @param {string} cell the row's value in the named column
 * @param {string} operator one of `=`, `!=`, `<`, `>`, `contains`
 * @param {string} value the operand from the command line
 * @returns {boolean} whether the row is kept
 */
function matches(cell, operator, value) {
  switch (operator) {
    case '=':
      return cell === value;
    case '!=':
      return cell !== value;
    case '<':
      return compare(cell, value) < 0;
    case '>':
      return compare(cell, value) > 0;
    default:
      // `contains` is a case-sensitive substring test, so an empty operand
      // matches every row.
      return cell.includes(value);
  }
}

/**
 * Keep the header and every row whose `column` cell matches.
 *
 * @param {{ header: string[], rows: string[][] }} table the parsed input
 * @param {string} column the column to test
 * @param {string} operator one of `=`, `!=`, `<`, `>`, `contains`
 * @param {string} value the operand to test against
 * @returns {{ header: string[], rows: string[][] }} the header and the
 *   matching rows, in file order
 * @throws {Error} `usage` when the operator is outside the five, `data` when
 *   the column is outside the header
 */
export function filter(table, column, operator, value) {
  // The command line is checked before the input, so a wrong operator is
  // reported even when the column is wrong too.
  if (!OPERATORS.has(operator)) {
    throw usageError(`unknown operator: ${operator}`);
  }
  const index = table.header.indexOf(column);
  if (index === -1) {
    throw dataError(`unknown column: ${column}`);
  }
  return {
    header: [...table.header],
    rows: table.rows.filter(row => matches(row[index], operator, value)),
  };
}
"}

