{"command":"cat > "$DSH_SCRATCHPAD/probe.mjs" <<'EOF'
import { filter } from './src/filter.js';
const t = (h, rows) => ({ header: h, rows });
const T = t(['v'], [['007'],['7'],['1e3'],['-2'],['0'],['+5'],['.5'],['NaN'],['Infinity'],['2.5']]);
const show = (op, val) => console.log(op, JSON.stringify(val), '->', filter(T,'v',op,val).rows.map(r=>r[0]).join('|'));
show('>', '5');            // numeric where both numbers; else code-unit strings
show('<', '10');
show('=', '007');
show('contains', '');
// exponent + rounding-free comparison
console.log('1e3>999:', filter(t(['v'],[['1e3']]),'v','>','999').rows.length === 1);
// zero-padded identifiers are text: '007' vs '7' -> '0'<'7' so 007 < 7
console.log('007<7 as text:', filter(t(['v'],[['007']]),'v','<','7').rows.length === 1);
// -0 is a number by the grammar? '-0' matches -?(0|...) => yes
console.log('-0 numeric vs 0:', filter(t(['v'],[['-0']]),'v','<','0').rows.length === 0);
// input table is not mutated, and header is a copy
const src = t(['v'], [['1'],['2']]);
const out = filter(src, 'v', '=', '1');
out.header.push('x'); out.rows.push(['9']);
console.log('no mutation:', JSON.stringify(src) === '{"header":["v"],"rows":[["1"],["2"]]}');
console.log('shape:', JSON.stringify(Object.keys(filter(src,'v','=','1'))));
// usage precedence when operator and column are both wrong
try { filter(src, 'nope', '~', 'x'); } catch (e) { console.log('precedence:', e.code, e.message); }
EOF
